let nodeReady=false,nodeChecked=false,activeProfile=Number(localStorage.getItem('energyActiveProfile'))||null,myProfiles=[],nodeUser=null,nodeCsrf='',nodeNeedsSetup=false,nodeRevision=0,nodeSaving=false,nodeWriteBlocked=false,nodeSaveTimer=null,nodeSaveChain=Promise.resolve();
const nativeEntry=entryView,nativeRegisterFields=registrationFields,nativeRender=render,nativeSave=save,nativeExit=leaveWorkspace;
function passwordInput(name,label,autocomplete='current-password'){return `<label>${label}<div class="password-input"><input name="${name}" type="password" required dir="ltr" autocomplete="${autocomplete}" ${autocomplete==='new-password'?'minlength="10" maxlength="128"':''}><button type="button" data-reveal="${name}" aria-label="إظهار كلمة المرور" aria-pressed="false">إظهار</button></div></label>`}
function validatePassword(password,confirm){if(password.length<10||password.length>128||!/[\p{L}]/u.test(password)||!/[0-9٠-٩]/.test(password))throw Error('كلمة المرور من ١٠ إلى ١٢٨ حرف، وتحتوي على حروف وأرقام.');if(password!==confirm)throw Error('تأكيد كلمة المرور غير مطابق.')}
registrationFields=function(){return nativeRegisterFields().replace('<div class="entry-flow-hint">',`<div class="entry-field-row">${passwordInput('password','كلمة المرور','new-password')}${passwordInput('passwordConfirm','تأكيد كلمة المرور','new-password')}</div><small class="password-help">١٠ أحرف على الأقل، حروف وأرقام. كلمة المرور لا تظهر للمدير.</small><div class="entry-flow-hint">`).replace('إرسال طلب تسجيل موظف للمعاينة','إنشاء الحساب وإرسال طلب الانضمام').replace('إرسال طلب تسجيل موظف','إنشاء الحساب وإرسال طلب الانضمام')};
loginFields=function(){if(entryTab==='setup')return `<form id="entryLogin" class="entry-form">${field('اسم المدير','name')}${field('بريد الإدارة المحدد في إعدادات السيرفر','email','email')}${options('الفرع الرئيسي','branch',db.branches.map(b=>b.name))}${passwordInput('setupToken','رمز إعداد الإدارة من إعدادات السيرفر','off')}${passwordInput('password','كلمة مرور المدير','new-password')}${passwordInput('passwordConfirm','تأكيد كلمة المرور','new-password')}<button class="primary entry-submit">تهيئة الإدارة للمرة الأولى</button></form>`;return `<form id="entryLogin" class="entry-form"><label>البريد الإلكتروني<input name="email" required type="email" autocomplete="username" dir="ltr" value="${esc(entryEmail)}" placeholder="name@example.com"></label>${passwordInput('password','كلمة المرور')}<button class="primary entry-submit">تسجيل الدخول ←</button><p class="entry-footnote">حساب جديد؟ التسجيل يحتاج موافقة الإدارة الأولى.</p><button type="button" id="backRegister" class="entry-text-button">تسجيل موظف جديد</button></form>`};
async function nodeApi(path,{method='GET',body}={}){if(!nodeReady)throw Error('قاعدة بيانات التطبيق غير متصلة حاليًا. تقدر تستكشف التصميم فقط، بدون تسجيل كلمة مرور.');const response=await fetch('/api/'+path,{method,credentials:'same-origin',headers:{'Content-Type':'application/json',...(method!=='GET'?{'X-CSRF-Token':nodeCsrf}:{})},...(body?{body:JSON.stringify(body)}:{})});let data;try{data=await response.json()}catch{throw Error('تعذر الاتصال بسيرفر التطبيق.')}if(!response.ok){if(data.error==='CONFLICT')nodeWriteBlocked=true;throw Object.assign(Error(data.message||'تعذر إتمام العملية'),{code:data.error})}if(data.csrf)nodeCsrf=data.csrf;return data}
function attachPasswordReveals(){document.querySelectorAll('[data-reveal]').forEach(b=>b.onclick=()=>{const input=b.closest('label').querySelector('input'),show=input.type==='password';input.type=show?'text':'password';b.textContent=show?'إخفاء':'إظهار';b.setAttribute('aria-pressed',String(show))})}
entryView=function(){nativeEntry();for(const selector of ['#entryRegister','#entryLogin']){const form=$(selector);if(form)form.replaceWith(form.cloneNode(true));}if($('#backRegister'))$('#backRegister').onclick=()=>{entryTab='register';entryMessage='';entryView()};const badge=$('.entry-preview-badge');if(badge)badge.textContent='ENERGY CLUB • STAFF';const hint=$('.entry-local-note');if(hint)hint.textContent=nodeReady?'الدخول وبيانات الفريق محفوظان على سيرفر التطبيق. كلمة المرور لا تُحفظ في المتصفح.':'نسخة العرض: خانات كلمة المرور جاهزة، والتسجيل الفعلي يتفعّل بعد توصيل قاعدة بيانات التطبيق.';$('#entryAdmin').textContent='دخول الإدارة ↗';$('#entryAdmin').onclick=()=>{entryTab='login';entryMessage='الإدارة تدخل ببريدها وكلمة المرور.';entryView()};const demo=document.createElement('button');demo.id='demoWorkspace';demo.type='button';demo.className='demo-workspace-link';demo.textContent='استكشاف نسخة العرض ببيانات تجريبية';demo.onclick=()=>enterWorkspace({kind:'admin'});if(!nodeReady)$('.entry-panel-main').append(demo);if(nodeReady&&nodeNeedsSetup){const setup=document.createElement('button');setup.className='server-setup-link';setup.type='button';setup.textContent='تهيئة حساب الإدارة للمرة الأولى';setup.onclick=()=>{entryTab='setup';entryMessage='التهيئة تتطلب رمز إعداد الإدارة من Hostinger؛ لا يوجد باسورد افتراضي.';entryView()};$('.entry-panel-main').append(setup)}attachPasswordReveals();if($('#entryRegister'))$('#entryRegister').onsubmit=async e=>{e.preventDefault();const form=e.target;form.querySelector('.entry-submit').disabled=true;try{const f=new FormData(form);validatePassword(String(f.get('password')),String(f.get('passwordConfirm')));await nodeApi('register',{method:'POST',body:{name:f.get('name'),email:f.get('email'),phone:f.get('phone'),position:f.get('position'),branch:f.get('branch'),password:f.get('password')}});entryEmail=String(f.get('email')).trim();entryMessage='تم استقبال طلب التسجيل. انتظر موافقة الإدارة الأولى ثم سجل دخولك.';entryTab='login';form.reset()}catch(err){entryMessage=err.message}finally{form.querySelectorAll('input[type="password"]').forEach(i=>i.value='');entryView()}};if($('#entryLogin'))$('#entryLogin').onsubmit=async e=>{e.preventDefault();const form=e.target;form.querySelector('.entry-submit').disabled=true;try{const f=new FormData(form);if(entryTab==='setup'){validatePassword(String(f.get('password')),String(f.get('passwordConfirm')));await nodeApi('bootstrap',{method:'POST',body:{name:f.get('name'),email:f.get('email'),branch:f.get('branch'),setupToken:f.get('setupToken'),password:f.get('password')}});nodeNeedsSetup=false;entryTab='login';entryEmail=String(f.get('email')).trim();entryMessage='تم إعداد الإدارة. سجل دخولك بكلمة المرور التي اخترتها.';entryView()}else{const data=await nodeApi('login',{method:'POST',body:{email:f.get('email'),password:f.get('password')}});nodeUser=data.user;await enterServerWorkspace()}}catch(err){entryMessage=err.message;entryView()}finally{form.querySelectorAll('input[type="password"]').forEach(i=>i.value='')}}};
async function enterServerWorkspace(){const data=await nodeApi('workspace'+(activeProfile?'?as='+activeProfile:''));db=data.db;nodeRevision=data.revision;myProfiles=data.myProfiles||[];if(activeProfile&&Number(data.activeProfile)!==activeProfile){activeProfile=null;localStorage.removeItem('energyActiveProfile')}nodeWriteBlocked=false;previewSession={kind:nodeUser.role==='employee'?'employee':'admin',employeeId:Number(nodeUser.id)};selectedEmployee=Number(nodeUser.id);role=nodeUser.role==='admin'?'الإدارة':nodeUser.role==='manager'?'مدير قسم':'الموظف';managerDepartment=positions[nodeUser.position];page=nodeUser.role==='admin'?'join-approvals':nodeUser.role==='manager'?'daily-team':'overview';entryRoot.hidden=true;render();if(nodeUser.role==='admin')await refreshServerMembers()}
async function refreshServerData(){if(nodeSaving)return toast('انتظر انتهاء الحفظ');if(nodeWriteBlocked&&!confirm('في تعديلات غير محفوظة بسبب تعارض. تحميل أحدث بيانات السيرفر؟'))return;const data=await nodeApi('workspace'+(activeProfile?'?as='+activeProfile:''));db=data.db;nodeRevision=data.revision;nodeWriteBlocked=false;myProfiles=data.myProfiles||[];if(activeProfile&&Number(data.activeProfile)!==activeProfile){activeProfile=null;localStorage.removeItem('energyActiveProfile')}render()}
function syncStatus(){const el=$('#serverSyncStatus');if(el)el.textContent=nodeWriteBlocked?'تعارض في التحديث — يلزم تحميل الأحدث':nodeSaving?'جارٍ الحفظ على السيرفر…':'متصل بسيرفر الفريق'}
save=function(){if(!nodeUser)return nativeSave();if(nodeUser.role!=='admin')return;clearTimeout(nodeSaveTimer);nodeSaving=true;syncStatus();nodeSaveTimer=setTimeout(()=>{nodeSaveChain=nodeSaveChain.then(async()=>{if(nodeWriteBlocked)throw Error('حدّث البيانات من السيرفر أولًا قبل حفظ تغييرات جديدة.');const snapshot=structuredClone(db);const result=await nodeApi('workspace',{method:'PUT',body:{db:snapshot,revision:nodeRevision}});nodeRevision=result.revision}).catch(e=>{nodeWriteBlocked=true;toast(e.message)}).finally(()=>{nodeSaving=false;syncStatus()})},350)};
async function nativeAction(action,data={}){if(!nodeUser)throw Error('يلزم تسجيل الدخول');const result=await nodeApi('workspace/action',{method:'POST',body:{action,data,...(activeProfile?{as:activeProfile}:{})}});db=result.db;nodeRevision=result.revision;render();return result}
let serverMembers=[];
async function refreshServerMembers(){if(nodeUser?.role!=='admin')return;const data=await nodeApi('members');serverMembers=data.members;if(page==='join-approvals')render()}
function serverApprovals(){return card('طلبات وحسابات الفريق — على السيرفر',`<div class="toolbar"><button id="refreshMembers">تحديث الطلبات</button></div>${serverMembers.filter(m=>m.role!=='admin').map(m=>`<div class="request"><div class="details"><strong>${esc(m.full_name)}</strong><p>${esc(m.email||'—')} • ${esc(m.phone||'—')}<br>${esc(m.requested_position||m.position||'—')} — ${esc(m.requested_branch||m.branch||'—')}</p></div><span class="badge">${({pending:'منتظر الموافقة',approved:'مقبول',rejected:'مرفوض',disabled:'موقوف'})[m.status]}</span><button data-native-review="${m.id}">${m.status==='pending'?'مراجعة':'إدارة الحساب'}</button>${m.status==='approved'?`<button data-native-reset="${m.id}">🔑 كلمة المرور</button>`:''}</div>`).join('')||'<p class="empty">لا توجد طلبات تسجيل جديدة.</p>'}`)}
function resetServerPassword(id){const m=serverMembers.find(m=>m.id===id);if(!m||nodeUser?.role!=='admin')return;openForm('تغيير كلمة المرور — '+m.full_name,'<p>بعد التغيير، الموظف يسجل دخوله بكلمة المرور الجديدة، وأي جلسة قديمة تتقفل تلقائيًا.</p>'+field('كلمة المرور الجديدة','password','password')+field('تأكيد كلمة المرور','passwordConfirm','password'),()=>{});const form=$('#form');form.querySelectorAll('input').forEach(i=>i.autocomplete='new-password');form.onsubmit=async e=>{e.preventDefault();const submit=form.querySelector('[type=submit]');if(submit.disabled)return;submit.disabled=true;try{const f=new FormData(form);validatePassword(String(f.get('password')),String(f.get('passwordConfirm')));await nodeApi('members/'+id+'/password',{method:'POST',body:{password:f.get('password')}});form.reset();$('#modal').close();toast('تم تغيير كلمة المرور')}catch(err){toast(err.message)}finally{submit.disabled=false}};$('#modal').addEventListener('close',()=>form.querySelectorAll('input[type=password]').forEach(i=>i.value=''),{once:true})}
function reviewServerAccount(id){const m=serverMembers.find(m=>m.id===id);safeSubmit('مراجعة '+m.full_name,options('الحالة','status',['قبول الحساب','رفض الطلب','إيقاف الحساب'])+options('الوظيفة المعتمدة','position',Object.keys(positions))+'<p id="rolePreview" class="notice"></p>'+options('الفرع','branch',db.branches.length?db.branches.map(b=>b.name):[m.requested_branch])+options('تسجيل الحضور من','branchAccess',['فرعه فقط','الفرعين','أي فرع'])+`<label>ربط الحساب بملف موظف مستورد (اختياري)<select name="legacyStaffId"><option value="">بدون ربط</option>${db.staff.filter(s=>s.legacyProfileId&&s.needsActivation).map(s=>`<option value="${s.id}">${esc(s.name)} — ${esc(s.employeeCode||'بدون كود')} — ${esc(s.branch)}</option>`).join('')}</select></label>`+field('ملاحظة القرار','reason'),async f=>{await nodeApi('members/'+id+'/review',{method:'POST',body:{status:({'قبول الحساب':'approved','رفض الطلب':'rejected','إيقاف الحساب':'disabled'})[f.get('status')],position:f.get('position'),branch:f.get('branch'),role:roleForTitle(f.get('position')),reason:f.get('reason'),legacyStaffId:f.get('legacyStaffId')||null}});await refreshServerMembers();await refreshServerData();const st=db.staff.find(s=>Number(s.id)===Number(id));if(st&&f.get('status')==='قبول الحساب'){st.branchAccess=({'فرعه فقط':'own','الفرعين':'both','أي فرع':'any'})[f.get('branchAccess')]||'own';save();render()}});const posSel=$('#fields select[name="position"]');posSel.value=m.position||m.requested_position;const updRolePreview=()=>{const r=roleForTitle(posSel.value);$('#rolePreview').textContent=r==='admin'?'الأكسس: إدارة كاملة — هيشتغل بعد إعادة تسجيل الدخول':r==='manager'?'الأكسس: مدير قسم '+positions[posSel.value]+' — هيشتغل بعد إعادة تسجيل الدخول':'الأكسس: موظف — هيشتغل بعد إعادة تسجيل الدخول'};posSel.onchange=updRolePreview;updRolePreview()}
const localAssign=createAssignment,localChange=changeTask,localCoach=recordCoaching,localLead=createLead,localBreakStart=startBreak,localBreakEnd=endBreak,localPunch=punch,localLeadUpdate=leadUpdateForm,localRequest=requestForEmployee,localReviewRequest=reviewRequest;

changeTask=function(id,action,note=''){if(!nodeUser||nodeUser.role==='admin')return localChange(id,action,note);return nativeAction(action==='submit'?'task_submit':'task_review',{id,note,approved:action==='approve'})};
recordCoaching=function(data){if(!nodeUser||nodeUser.role==='admin')return localCoach(data);return nativeAction('coach_create',data)};
createLead=function(data){if(!nodeUser||nodeUser.role==='admin')return localLead(data);return nativeAction('sales_create',data)};
startBreak=function(id,source='employee',reason=''){if(!nodeUser||nodeUser.role==='admin')return localBreakStart(id,source,reason);return nativeAction('break_start')};
endBreak=function(id,source='employee',reason=''){if(!nodeUser||nodeUser.role==='admin')return localBreakEnd(id,source,reason);return nativeAction('break_end')};
punch=function(){if(!nodeUser)return localPunch();if(geoBusy)return;const out=!!activePunch(Number(nodeUser.id));if(out&&activeBreak(Number(nodeUser.id)))return toast('أنهِ البريك أولًا');if(!navigator.geolocation)return toast('المتصفح لا يدعم الموقع');geoBusy=true;render();navigator.geolocation.getCurrentPosition(async p=>{try{if(Date.now()-p.timestamp>30000)throw Error('قراءة الموقع قديمة؛ أعد المحاولة');await nativeAction(out?'punch_out':'punch_in',{coords:{latitude:p.coords.latitude,longitude:p.coords.longitude,accuracy:p.coords.accuracy}});toast('تم التسجيل بعد التحقق من موقع الفرع')}catch(e){toast(e.message)}finally{geoBusy=false;render()}},()=>{geoBusy=false;render();toast('تعذر الوصول للموقع. اسمح بالموقع الدقيق وحاول تاني.')},{enableHighAccuracy:true,maximumAge:0,timeout:20000})};
leadUpdateForm=function(id){if(!nodeUser||nodeUser.role==='admin')return localLeadUpdate(id);const l=db.salesLeads.find(l=>l.id===id);if(!l)return;safeSubmit('متابعة '+l.name,options('المرحلة','stage',leadStages)+options('نتيجة المكالمة','outcome',callOutcomes)+'<label>الخطة / الباقة (اختياري)<input name="plan" type="text" maxlength="120" value="'+String(l.plan||'').replace(/"/g,'&quot;')+'"></label><label>تاريخ انتهاء الاشتراك (اختياري)<input name="expiryDate" type="date" value="'+(l.expiryDate||'')+'"></label>'+field('الخطوة الجاية','nextAction','text',l.nextAction||'')+'<label>موعد المتابعة بتوقيت القاهرة<input name="followUp" type="datetime-local"></label><label>الكومنت / ملاحظات المتابعة<textarea name="comment" required rows="4" maxlength="2000" placeholder="العميل قال إيه؟ واتفقتم على إيه؟"></textarea></label>',async f=>nativeAction('sales_followup',{id,stage:f.get('stage'),outcome:f.get('outcome'),nextAction:f.get('nextAction'),nextFollowUp:f.get('followUp')?cairoToISO(f.get('followUp')):'',comment:f.get('comment'),plan:f.get('plan'),expiryDate:f.get('expiryDate')}))};
requestForEmployee=function(){if(!nodeUser)return localRequest();safeSubmit('طلب جديد',options('نوع الطلب','type',['إجازة اعتيادية','إجازة مرضية','إذن انصراف مبكر','إذن تأخير وصول','إذن خروج وعودة أثناء الوردية','تصحيح بصمة','تبديل وردية'])+field('التفاصيل','detail')+'<label>اليوم (اختياري)<input name="day" type="date"></label><label>عدد الساعات (اختياري)<input name="hours" type="number" min="0.5" max="24" step="0.5"></label>',async f=>nativeAction('request_create',{type:f.get('type'),detail:f.get('detail'),day:f.get('day')||undefined,hours:f.get('hours')||undefined}))};
reviewRequest=function(id,approved){if(!nodeUser||nodeUser.role==='admin')return localReviewRequest(id,approved);const r=db.requests.find(r=>String(r.id)===String(id));if(!r)return;const hoursField=approved?`<label>عدد الساعات المعتمدة<input name="hours" type="number" min="0.5" max="24" step="0.5" value="${r.hours||''}"></label>`:'';safeSubmit((approved?'قبول':'رفض')+' طلب '+r.name+' — '+r.type,(approved?options('الاحتساب','paid',['مدفوع','غير مدفوع']):'')+hoursField+(approved?'':field('سبب الرفض','note')),async f=>nativeAction('request_review',{id,approved,paid:f.get('paid')==='مدفوع',hours:f.get('hours')||undefined,note:f.get('note')||undefined}))};
leaveWorkspace=async function(){if(nodeUser&&nodeSaving){toast('انتظر اكتمال حفظ البيانات قبل الخروج.');return}if(nodeUser){try{await nodeApi('logout',{method:'POST'})}catch(e){toast('تعذر تسجيل الخروج من السيرفر؛ حاول تاني.');return}}nodeUser=null;nodeRevision=0;nodeWriteBlocked=false;serverMembers=[];$('#role').disabled=false;nativeExit();await checkHostingerServer()};
render=function(){if(nodeUser){role=nodeUser.role==='admin'?'الإدارة':nodeUser.role==='manager'?'مدير قسم':'الموظف';selectedEmployee=Number(nodeUser.id);if(nodeUser.role==='manager')managerDepartment=positions[nodeUser.position]}nativeRender();if(!nodeUser||!previewSession)return;$('#role').hidden=true;$('#role').disabled=true;for(const name of ['managerDept','finalManagerDept'])if($('#'+name))$('#'+name).disabled=true;$('.demo').textContent='دخول بكلمة مرور';if(!$('#serverSyncStatus')){$('#app').insertAdjacentHTML('afterbegin','<div class="notice"><span id="serverSyncStatus"></span><button id="reloadServer">تحديث البيانات</button></div>');$('#reloadServer').onclick=()=>refreshServerData().catch(e=>toast(e.message))}const navEl=document.querySelector('#nav');if(navEl&&myProfiles.length>1&&!$('#profileSwitcher')){navEl.insertAdjacentHTML('afterbegin','<select id="profileSwitcher" style="margin:8px;width:90%" title="تبديل البروفايل">'+myProfiles.map(p=>'<option value="'+p.id+'" '+((activeProfile||Number(nodeUser.id))===p.id?'selected':'')+'>'+esc(p.name)+' — '+esc(p.position||'')+(p.primary?' (حسابي)':'')+'</option>').join('')+'</select>');$('#profileSwitcher').onchange=e=>{const v=Number(e.target.value);if(v===Number(nodeUser.id)){activeProfile=null;localStorage.removeItem('energyActiveProfile')}else{activeProfile=v;localStorage.setItem('energyActiveProfile',String(v))}refreshServerData().catch(err=>toast(err.message))}}syncStatus();
if(nodeUser){
 const ownAddPages=['accounts','branch-access','classes'];
 if(nodeUser.role==='admin'&&!ownAddPages.includes(page)){$('#add').hidden=false;$('#add').textContent='＋ تجهيز حساب موظف';$('#add').onclick=()=>{page='rollout-readiness';render()}}
 const tasksBtn=document.querySelector('#nav [data-page="tasks"]');if(tasksBtn)tasksBtn.hidden=true;
 if(page==='requests'&&(nodeUser.role==='admin'||nodeUser.role==='manager'))renderTeamRequests();
 if(page==='shifts'){$('#app').innerHTML='<div class="notice">تعيين الشفتات ومتابعتها بقوا من صفحة «جدول شفتات الموظفين». <button id="goShiftPlanner" class="primary">افتح جدول الشفتات ←</button></div>';$('#goShiftPlanner').onclick=()=>{page='shift-planner';render()}}
 if(page==='permissions'){$('#app').innerHTML='<div class="notice">إدارة الأكسس الفعلية: دور كل حساب (موظف / مدير قسم / إدارة) من صفحة «الحسابات والأكسس»، وفروع تسجيل الحضور لكل موظف من «أكسس حضور الفروع». الصفحة دي كانت معاينة قديمة — إعداداتها ما كانتش بتتطبق فعليًا — واتقفلت عشان متعملش لبس.</div>'}
}
if(page==='join-approvals'&&nodeUser.role==='admin'){$('#app').innerHTML=serverApprovals();$('#refreshMembers').onclick=()=>refreshServerMembers().catch(e=>toast(e.message));document.querySelectorAll('[data-native-review]').forEach(b=>b.onclick=()=>reviewServerAccount(Number(b.dataset.nativeReview)));document.querySelectorAll('[data-native-reset]').forEach(b=>b.onclick=()=>resetServerPassword(Number(b.dataset.nativeReset)))}};
async function checkHostingerServer(){try{const response=await fetch('/api/health',{credentials:'same-origin',cache:'no-store'}),health=await response.json();nodeReady=!!health.ready;if(nodeReady){const s=await nodeApi('session');nodeCsrf=s.csrf;nodeNeedsSetup=s.needsSetup;const registration=await nodeApi('registration-options');db.branches=registration.branches.map(name=>({name,lat:null,lng:null}));if(s.user?.status==='approved'){nodeUser=s.user;await enterServerWorkspace();return}}}catch{nodeReady=false}finally{nodeChecked=true}if(!previewSession)entryView()}
setInterval(async()=>{if(!nodeUser)return;try{const s=await nodeApi('session');if(!s.user||s.user.status!=='approved'){nodeUser=null;previewSession=null;entryMessage='الجلسة انتهت أو الحساب موقوف. سجل دخولك من جديد.';entryView()}}catch{}},60000);
let reqFilter={status:'all',type:'all',q:''};
function renderTeamRequests(){
 const types=[...new Set((db.requests||[]).map(r=>r.type))];
 const rows=(db.requests||[]).filter(r=>(reqFilter.status==='all'||r.status===reqFilter.status)&&(reqFilter.type==='all'||r.type===reqFilter.type)&&(!reqFilter.q||String(r.name).includes(reqFilter.q))).slice().reverse();
 const rowHtml=rows.map(r=>`<div class="request"><div class="initial">${esc(String(r.name||'?')[0])}</div><div class="details"><strong>${esc(r.name)} <span style="color:#a2aaa4;font-weight:400">/ ${esc(r.type)}</span></strong><p>${esc(r.detail||'')}</p>${requestMeta(r)}${r.onBehalf?`<p class="muted">أنشأه ${esc(r.createdBy||'الإدارة')} نيابة عن الموظف</p>`:''}${r.reviewedBy?`<p class="muted">راجعه: ${esc(r.reviewedBy)}${r.reviewedAt?' — '+String(r.reviewedAt).slice(0,10):''}</p>`:''}</div>${r.status==='معلق'?`<button data-approve="${r.id}">✓</button><button class="reject" data-reject="${r.id}">✕</button>`:badge(r.status)}</div>`).join('')||'<div class="empty">مفيش طلبات مطابقة للفلتر الحالي.</div>';
 $('#app').innerHTML=`<section class="card"><div class="card-head"><h2>طلبات الفريق</h2><button id="requestNew" class="primary">＋ إضافة طلب لموظف</button></div><div class="toolbar" style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:12px"><select id="reqStatus"><option value="all">كل الحالات</option>${['معلق','مقبول','مرفوض'].map(s=>`<option ${reqFilter.status===s?'selected':''}>${s}</option>`).join('')}</select><select id="reqType"><option value="all">كل الأنواع</option>${types.map(t=>`<option ${reqFilter.type===t?'selected':''}>${esc(t)}</option>`).join('')}</select><input id="reqQ" type="search" placeholder="ابحث باسم الموظف…" value="${esc(reqFilter.q)}"><span class="muted">${rows.length} طلب</span></div><div id="reqRows">${rowHtml}</div></section>`;
 $('#requestNew').onclick=requestForStaff;
 $('#reqStatus').onchange=e=>{reqFilter.status=e.target.value;renderTeamRequests()};
 $('#reqType').onchange=e=>{reqFilter.type=e.target.value;renderTeamRequests()};
 $('#reqQ').oninput=e=>{reqFilter.q=e.target.value.trim();renderTeamRequests();const q=$('#reqQ');q.focus();q.setSelectionRange(q.value.length,q.value.length)};
 document.querySelectorAll('[data-approve]').forEach(b=>b.onclick=()=>reviewRequest(b.dataset.approve,true));
 document.querySelectorAll('[data-reject]').forEach(b=>b.onclick=()=>reviewRequest(b.dataset.reject,false));
}
function requestForStaff(){
 const people=(db.staff||[]).filter(s=>!s.needsActivation).slice().sort((a,b)=>String(a.name).localeCompare(String(b.name),'ar'));
 if(!people.length)return toast('مفيش موظفين متاحين في نطاقك');
 safeSubmit('إضافة طلب لموظف','<label>الموظف<select name="employeeId" required>'+people.map(s=>`<option value="${s.id}">${esc(s.name)} — ${esc(s.position||s.job||'')}</option>`).join('')+'</select></label>'+options('نوع الطلب','type',['إجازة اعتيادية','إجازة مرضية','إذن انصراف مبكر','إذن تأخير وصول','إذن خروج وعودة أثناء الوردية','تصحيح بصمة','تبديل وردية'])+field('التفاصيل','detail')+'<label>اليوم (اختياري)<input name="day" type="date"></label><label>عدد الساعات (اختياري)<input name="hours" type="number" min="0.5" max="24" step="0.5"></label>',async f=>{await nativeAction('request_create_for',{employeeId:Number(f.get('employeeId')),type:f.get('type'),detail:f.get('detail'),day:f.get('day')||undefined,hours:f.get('hours')||undefined});toast('تم إضافة الطلب')});
}
render();checkHostingerServer();
setInterval(()=>{if(!nodeReady&&!previewSession)checkHostingerServer()},15000);

$('#closeModal').onclick=()=>$('#modal').close();

function changeAccountPassword(){
 if(!nodeUser)return;
 safeSubmit('تغيير كلمة المرور',
  passwordInput('currentPassword','كلمة المرور الحالية')+
  passwordInput('password','كلمة المرور الجديدة','new-password')+
  passwordInput('passwordConfirm','تأكيد كلمة المرور الجديدة','new-password')+
  '<p>بعد الحفظ، سيتم تسجيل الخروج من الأجهزة الأخرى. سيظل حسابك مفتوحًا على هذا الجهاز.</p>',
  async f=>{
   validatePassword(String(f.get('password')),String(f.get('passwordConfirm')));
   await nodeApi('password',{method:'POST',body:{currentPassword:f.get('currentPassword'),password:f.get('password')}});
   toast('تم تغيير كلمة المرور وإغلاق الجلسات القديمة.');
  });
 attachPasswordReveals();
}
const renderBeforeAccountSettings=render;
render=function(){
 renderBeforeAccountSettings();
 if(!nodeUser||!previewSession)return;
 document.querySelectorAll('[data-preview-only]').forEach(el=>el.remove());
 const employeeSelector=$('#employeeSelect');if(employeeSelector){employeeSelector.disabled=true;employeeSelector.closest('.toolbar').hidden=true;}
 const localJoin=$('#nav [data-page="join"]');if(localJoin)localJoin.hidden=true;
 if(nodeUser.role==='employee'&&page==='overview'){
  const day=cairoDay(),hours=attendanceHours(Number(nodeUser.id),{from:day,to:day}).hours;
  const tasks=db.dailyAssignments.filter(t=>Number(t.employeeId)===Number(nodeUser.id)&&t.day===day);
  $('#app').insertAdjacentHTML('afterbegin',`<section class="employee-welcome"><div><span class="eyebrow">YOUR SPACE · YOUR PROGRESS</span><h2>أهلًا، <span translate="no">${esc(nodeUser.full_name)}</span></h2><p>${esc(nodeUser.position)} · ${esc(nodeUser.branch)} · ${esc(positions[nodeUser.position])}</p>${nodeUser.email?`<small dir="ltr">${esc(nodeUser.email)}</small>`:''}</div><div class="employee-day-stats"><div><strong>${hours.toFixed(1)}</strong><span>ساعة حضور مكتملة اليوم</span></div><div><strong>${tasks.filter(t=>['assigned','returned'].includes(t.status)).length}</strong><span>مهمة مطلوبة منك اليوم</span></div><div><strong>${tasks.filter(t=>t.status==='approved').length}</strong><span>مهمة معتمدة</span></div></div><button type="button" id="openMyDailyTasks">افتح مهامي اليومية ←</button></section>`);
  $('#openMyDailyTasks').onclick=()=>{page='daily-team';render()};
 }
 const actions=$('.header-actions');
 if(actions&&!$('#changeAccountPassword')){
  actions.insertAdjacentHTML('afterbegin','<button type="button" id="changeAccountPassword">تغيير كلمة المرور</button>');
  $('#changeAccountPassword').onclick=changeAccountPassword;
 }
};

// تحديث تلقائي للبيانات: قبل كده الرسايل والإعلانات الجديدة ما كانتش بتظهر للموظف
// اللي فاتح التطبيق إلا بعد reload يدوي أو زرار «تحديث البيانات». كل ٣٠ ثانية بنسحب
// أحدث نسخة من السيرفر، مع تخطي الدورة لو المستخدم بيكتب في خانة أو فاتح نافذة إدخال
// عشان ما يضيعش اللي بيكتبه، والحفاظ على مسودة رسالة الشات لو بيكتبها.
setInterval(async()=>{
 try{
  if(!nodeUser||document.hidden||nodeSaving||nodeWriteBlocked)return;
  if(document.querySelector('#modal[open]'))return;
  let draft=null,focused=false;
  if(page==='chat'){
   const inp=document.querySelector('#x-chat-body');
   if(inp){draft=inp.value;focused=document.activeElement===inp}
  }else{
   const typing=[...document.querySelectorAll('#app input,#app textarea')].some(el=>el.type!=='checkbox'&&el.type!=='radio'&&el.value&&String(el.value).trim());
   if(typing)return;
  }
  const lastAt=db&&Array.isArray(db.chatMessages)&&db.chatMessages.length?String(db.chatMessages[db.chatMessages.length-1].at):'';
  await refreshServerData();
  if(page==='chat'&&draft!=null){
   const inp2=document.querySelector('#x-chat-body');if(inp2){inp2.value=draft;if(focused)inp2.focus()}
  }else if(db&&Array.isArray(db.chatMessages)&&db.chatMessages.length&&String(db.chatMessages[db.chatMessages.length-1].at)!==lastAt){
   toast('في رسايل جديدة في شات الفريق 💬');
  }
 }catch(e){/* الدورة الجاية هتحاول تاني */}
},30000);

// صفحة «أكسس كل موظف»: كل حسابات الدخول الحقيقية على السيرفر ووصول كل شخص في مكان واحد.
navs.push(['staff-access','⚿','أكسس كل موظف']);
const STAFF_ACCESS_ITEMS=[['attendance','الحضور والانصراف'],['records','سجل الحضور'],['requests','الطلبات'],['tasks','المهام'],['shifts','الشفتات'],['breaks','البريكات'],['classes','الكلاسات'],['sales','السيلز والمكالمات'],['score','التقييم والنقاط'],['reports','التقارير'],['staff','فريق العمل'],['payroll','المرتبات']];
function staffAccessScope(m){
 if(m.role==='admin')return '<small><b>إدارة كاملة:</b> كل البنود على الفرعين</small>';
 if(m.role!=='manager')return '<small>بياناته الشخصية (حضوره، مهامه، طلباته، نقاطه) + الشات ولائحة العمل</small>';
 const g=((db.accessMatrix&&db.accessMatrix.grants)||{})[m.position];
 if(!g)return '<small>مدير — مفيش نطاقات محفوظة لمسماه في مصفوفة الأكسس</small>';
 const byLevel={edit:[],approve:[],view:[]};
 STAFF_ACCESS_ITEMS.forEach(([item,label])=>{const c=g[item];const lvl=c&&c.level||'none';if(byLevel[lvl])byLevel[lvl].push(label)});
 const names={edit:'تعديل',approve:'اعتماد',view:'عرض'};
 return ['edit','approve','view'].map(l=>byLevel[l].length?`<small><b>${names[l]}:</b> ${byLevel[l].join('، ')}</small>`:'').filter(Boolean).join('<br>')||'<small>—</small>';
}
function staffAccessView(){
 const stById={};(db.staff||[]).forEach(s=>stById[String(s.id)]=s);
 const order={approved:0,pending:1,disabled:2,rejected:3};
 const members=(serverMembers||[]).slice().sort((a,b)=>(order[a.status]??4)-(order[b.status]??4)||String(a.full_name).localeCompare(String(b.full_name),'ar'));
 const rows=members.map(m=>{
  const st=stById[String(m.id)]||{};
  const roleLabel=m.role==='admin'?'إدارة':m.role==='manager'?'مدير قسم':'موظف';
  const ba=st.branchAccess||'own';
  const baLabel=ba==='both'?'الفرعين':ba==='any'?'أي فرع':'فرعه فقط';
  const statusLabel=({pending:'منتظر الموافقة',approved:'مقبول',rejected:'مرفوض',disabled:'موقوف'})[m.status]||m.status;
  return `<tr><td><b>${esc(m.full_name)}</b><br><small>${esc(m.email||'—')}</small></td><td>${esc(m.position||'—')}<br><small>${esc(st.department||'')}</small></td><td>${roleLabel}<br><small>${statusLabel}</small></td><td>${esc(m.branch||st.branch||'—')}<br><small>البصمة: ${baLabel}</small></td><td style="min-width:240px">${staffAccessScope(m)}</td><td><button type="button" data-sa-review="${m.id}">إدارة الحساب</button></td></tr>`;
 }).join('');
 return card('أكسس كل موظف — كل حسابات الدخول ووصولها',`<p class="empty" style="margin:0 0 12px">دي النظرة المجمعة لكل حساب دخول على السيرفر. تغيير الدور أو المسمى أو الفرع بيتم من زرار «إدارة الحساب»، فروع البصمة التفصيلية لكل موظف من صفحة «أكسس حضور الفروع»، ونطاقات المديرين التفصيلية من «مصفوفة الأكسس».</p><div class="table-wrap"><table><tr><th>الموظف</th><th>المسمى / القسم</th><th>الدور / الحالة</th><th>الفرع / البصمة</th><th>الوصول المسموح</th><th></th></tr>${rows||'<tr><td colspan="6">لا توجد حسابات بعد</td></tr>'}</table></div>`);
}
const staffAccessPrevRender=render;
render=function(){staffAccessPrevRender();const saNav=document.querySelector('#nav');if(saNav&&nodeUser&&nodeUser.role==='admin'&&!saNav.querySelector('[data-staff-access]')){const b=document.createElement('button');b.dataset.staffAccess='1';b.innerHTML='<i>'+navIcon('access-matrix')+'</i> أكسس كل موظف';b.onclick=()=>{page='staff-access';render()};const anchor=saNav.querySelector('[data-page="access-matrix"]');anchor?anchor.after(b):saNav.append(b)};if(page==='staff-access'){if(!nodeUser||nodeUser.role!=='admin'){$('#app').innerHTML='<p class="empty">صفحة خاصة بالإدارة</p>';return}$('#app').innerHTML=staffAccessView();document.querySelectorAll('[data-sa-review]').forEach(b=>b.onclick=()=>reviewServerAccount(Number(b.dataset.saReview)))}};
